@@ -0,0 +1,45 @@
+const canvas = document.getElementById('paint-canvas');
+const ctx = canvas.getContext('2d');
+canvas.width = window.innerWidth;
+canvas.height = window.innerHeight;
+
+let isDrawing = false;
+let lastX = 0;
+let lastY = 0;
+let color = 'black';
+let size = 10;
+
+function draw(e) {
+    if (!isDrawing) return; // stop the fn from running when they are not moused down
+    ctx.beginPath();
+    ctx.strokeStyle = color;
+    ctx.lineWidth = size;
+    ctx.lineCap = 'round';
+    ctx.lineJoin = 'round';
+    ctx.moveTo(lastX, lastY);
+    ctx.lineTo(e.offsetX, e.offsetY);
+    ctx.stroke();
+    [lastX, lastY] = [e.offsetX, e.offsetY];
+}
+
+function updateLastPos(e) {
+    [lastX, lastY] = [e.offsetX, e.offsetY];
+}
+
+canvas.addEventListener('mousedown', (e) => {
+    isDrawing = true;
+    [lastX, lastY] = [e.offsetX, e.offsetY];
+});
+canvas.addEventListener('mousemove', draw);
+canvas.addEventListener('mouseup', () => isDrawing = false);
+canvas.addEventListener('mouseout', () => isDrawing = false);
+
+const colorInputs = document.querySelectorAll('.color-picker input');
+colorInputs.forEach(input => {
+    input.addEventListener('input', (e) => color = `rgb(${e.target.value}, ${e.target.value}, ${e.target.value})`);
+});
+
+const sizeInput = document.getElementById('size');
+sizeInput.addEventListener('input', (e) => size = e.target.value);
+
+document.getElementById('clear-button').addEventListener('click', () => ctx.clearRect(0, 0, canvas.width, canvas.height));

